import React, { useState } from 'react';
import './styles.css';

export default function App() {
  const [redScore, setRedScore] = useState(0);
  const [blueScore, setBlueScore] = useState(0);

  return (
    <main className="scoreboard">
      <h1 className="scoreboard-title">双人比赛记分牌</h1>
      <div className="teams">
        <section className="team team-red" data-testid="team-red">
          <h2 className="team-name">红队</h2>
          <p className="team-score" data-testid="score-red">{redScore}</p>
          <div className="team-actions">
            <button type="button" className="score-btn" onClick={() => setRedScore((prev) => prev + 1)}>加 1 分</button>
            <button type="button" className="score-btn" onClick={() => setRedScore((prev) => prev - 1)}>减 1 分</button>
          </div>
        </section>
        <section className="team team-blue" data-testid="team-blue">
          <h2 className="team-name">蓝队</h2>
          <p className="team-score" data-testid="score-blue">{blueScore}</p>
          <div className="team-actions">
            <button type="button" className="score-btn" onClick={() => setBlueScore((prev) => prev + 1)}>加 1 分</button>
            <button type="button" className="score-btn" onClick={() => setBlueScore((prev) => (prev > 0 ? prev - 1 : 0))}>减 1 分</button>
          </div>
        </section>
      </div>
      <p className="status" data-testid="status">平局</p>
    </main>
  );
}

